import sys
from itertools import permutations

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def max_primes(perm):
    prefix_sum = 0
    prime_count = 0
    for num in perm:
        prefix_sum += num
        if is_prime(prefix_sum):
            prime_count += 1
    return prime_count

